      performOperation={async () => {
        let finalMemo = memo;
        if (memo.length && memo[0] === '#') {
          console.log('pwait');
          const receiverMemoKey = (await getAccountKeys(to.toLowerCase())).memo;
          finalMemo = await encodeMemo(
            getAccountMemoKey(),
            receiverMemoKey,
            memo,
          );
          console.log(finalMemo);
