export const getSaliencyColor = (value: number): string => {
	var color: [number, number, number] | null = null;
	if (value < 0) {
		color = [52, 152, 219];
	} else {
		color = [231, 76, 60];
	}
	return colorToString(interpolate(Math.abs(value), [255, 255, 255], color));
};

const interpolate = (
	val: number,
	rgb1: [number, number, number],
	rgb2: [number, number, number]
): [number, number, number] => {
	if (val > 1) {
		val = 1;
	}
	val = Math.sqrt(val);
	var rgb: [number, number, number] = [0, 0, 0];
	var i;
	for (i = 0; i < 3; i++) {
		rgb[i] = Math.round(rgb1[i] * (1.0 - val) + rgb2[i] * val);
	}
	return rgb;
};

const colorToString = (rgb: [number, number, number]): string => {
	return "rgb(" + rgb[0] + ", " + rgb[1] + ", " + rgb[2] + ")";
};

export function getObjectFitSize(
	contains: boolean /* true = contain, false = cover */,
	containerWidth: number,
	containerHeight: number,
	width: number,
	height: number
): { width: number; height: number; x: number; y: number } {
	var doRatio = width / height;
	var cRatio = containerWidth / containerHeight;
	var targetWidth = 0;
	var targetHeight = 0;
	var test = contains ? doRatio > cRatio : doRatio < cRatio;

	if (test) {
		targetWidth = containerWidth;
		targetHeight = targetWidth / doRatio;
	} else {
		targetHeight = containerHeight;
		targetWidth = targetHeight * doRatio;
	}

	return {
		width: targetWidth,
		height: targetHeight,
		x: (containerWidth - targetWidth) / 2,
		y: (containerHeight - targetHeight) / 2
	};
}

package davserver.protocol;

import java.io.IOException;

import javax.xml.parsers.ParserConfigurationException;

import org.apache.http.HttpEntityEnclosingRequest;
import org.apache.http.HttpRequest;
import org.apache.http.HttpResponse;
import org.pmw.tinylog.Logger;
import org.w3c.dom.Document;
import org.xml.sax.SAXException;

import davserver.DAVException;
import davserver.DAVUrl;
import davserver.DAVUtil;
import davserver.protocol.acl.properties.ACL;
import davserver.protocol.auth.Session;
import davserver.repository.IRepository;
import davserver.repository.error.ConflictException;
import davserver.repository.error.NotAllowedException;
import davserver.repository.error.NotFoundException;
import davserver.utils.XMLParser;

/**
 * ACL Implementation
 * 
 * @author tkrieger
 *
 */
public class DAVACL extends DAVRequest {

	@Override
	public void handle(HttpRequest breq, HttpResponse resp, IRepository repos, DAVUrl url,Session session)
			throws DAVException, NotFoundException, NotAllowedException, ConflictException {
		HttpEntityEnclosingRequest req;
		ACL acl = null;

		// check request
		if (!(breq instanceof HttpEntityEnclosingRequest)) {
			throw new DAVException(400,"no body");
		}
		req = (HttpEntityEnclosingRequest)breq;


		if (req.getEntity().getContentLength() > 0) {
			try {
				Document body = XMLParser.singleton().parseStream(req.getEntity().getContent());
				System.out.println("got a acl body: " + body);
				Logger.debug(DAVUtil.debug(body));
				acl = ACL.parse(body);
			} catch (UnsupportedOperationException e) {
				throw new DAVException(400,e.getMessage());
			} catch (SAXException e) {
				throw new DAVException(400,e.getMessage());
			} catch (IOException e) {
				throw new DAVException(500,e.getMessage());
			} catch (ParserConfigurationException e) {
				throw new DAVException(500,e.getMessage());
			} 

			// update acl content
			repos.getACLProvider().updateACL(url.getResref(), acl);

		} else {
			System.out.println("no acl body!");
		}
	}

}

import _ from 'lodash'

// interface
import { Block } from '../type'

// function

export function encodeFnName(
  name: string
): string {

  name = name
    .replace(/\]/g, '')
    .replace(/\[/g, '.')
    .replace(/\./g, '_dot_')

  return `__${name}__`
}

export function formatKey(
  input: string
): string {

  return input
    .toLowerCase()
    .replace(/['"]/g, '')
    .replace(/\-/g, '')
    // ---
    .replace(/equal/g, '=')
    .replace(/minus/g, '-')
    .replace(/num/g, 'numpad')
    .replace(/padpad/g, 'pad')
    .replace(/pagedown/g, 'pgdn')
    .replace(/pageup/g, 'pgup')
    .replace(/plus/g, '+')
    // ---
    .replace(/:/g, ' ')
}

export function getDepth(
  line: string
): number {
  return Math.floor((line.length - line.trimStart().length) / 2)
}

export function initBlock(): Block {
  return {
    name: '',
    argument: [],
    content: []
  }
}

export function regFn(
  listFn: Block[],
  name: string,
  argument: string[],
  content: string[]
): string {

  name = encodeFnName(name)
  content.push('')

  if (~_.findIndex(listFn, { name })) return name

  listFn.push({
    name,
    argument,
    content
  })

  return name
}

export function setDepth(
  n: number
): string {
  return _.repeat(' ', n * 2)
}

export function trim(
  input: string
): string {

  if (!["'", '"'].includes(input[0])) return input
  return input.slice(1, (input.length - 1))
}

export function unquote(
  line: string
): string {

  if (!line.includes('#{')) return line

  return line
    .replace(/#{/g, '" . ')
    .replace(/}/g, ' . "')
    .replace(/\.\s*""\s*\./g, '.')
    .replace(/"\s*\.\s*\.\s*"/g, '')
}

