public class Shield 
{
	public TheGameObject slave;
	private TheScript slave_script = null;

	public bool front_shield = false;
	public bool back_shield = false;


	void Start () 
	{
		if(slave != null)
			slave_script = slave.GetScript("PlayerMovement");

		TheConsole.Log(slave.name);
	}

	void Update () 
	{

	}


	void OnTriggerEnter(TheCollisionData coll)
	{

		if(coll == null)
			return;

		TheGameObject colision_object = coll.Collider.GetGameObject();

		if(colision_object == null)
			return;

		TheScript laser = colision_object.GetScript("Laser");

		TheGameObject sender = (TheGameObject)laser.CallFunctionArgs("GetSender");

		if(laser != null && slave_script != null && sender.GetComponent<TheTransform>() != slave.GetComponent<TheTransform>())
		{
			int dmg = (int)laser.CallFunctionArgs("GetDamage");
			object[] args = {dmg};
			colision_object.SetActive(false);

			if(front_shield && back_shield)
				TheConsole.Log("Invalid Shield Options");
			else if(front_shield)
				slave_script.CallFunctionArgs("DamageFrontShield", args);
			else if(back_shield)
				slave_script.CallFunctionArgs("DamageBackShield", args);
			else
				TheConsole.Log("Invalid Shield Options");

		}

	}
}

import 'phaser';
import Team from '../utils/Team';
import BattlezoneScene from '../scenes/BattlezoneScene';
import Player from './Player';

import Sprite = Phaser.GameObjects.Sprite;
import Group = Phaser.GameObjects.Group;

class Bullet extends Sprite {
    scene: BattlezoneScene;
    host: any;
    speed: number;
    life: number;
    constructor(scene: BattlezoneScene,
        spawnPoint: [number, number],
        direction: number, host: any) {
        super(scene, spawnPoint[0], spawnPoint[1], 'bullet');
        this.scene = scene;
        this.scene.add.existing(this);

        if (host.team === Team.Red) {
            this.setTexture('bullet');
            (this.scene.bulletsGroup as Group).add(this);
        } else {
            this.setTexture('bullet_pink');
            (this.scene.monsterBulletGroup as Group).add(this);
        }
        this.life = 75;
        this.host = host;

        this.scene.physics.add.existing(this);
        this.speed = 550;
        this.body.velocity.x = Math.cos(direction) * this.speed;
        this.body.velocity.y = Math.sin(direction) * this.speed;

        this.scene.events.on('update', () => {
            this.update()
        });
    }
    update() {
        super.update();
        this.life--;

        if (this.life <= 0) {
            this.destroy();
        }
    }
}

export {Bullet as default};

import React from 'react';

import Config from '../config';
import Utils from '../utils';
import './Edit.css';
import Sider from "../Public/Sider";
import Header from "../Public/Header";

class Edit extends React.Component {

    constructor(props){
        super(props);
        document.title = 'Member Edit';
        let $this = this;
        $this.state = {
            memberCopy: {},
            member: {username: '', email: '', group:'', groupObj: {}},
            id: props.match.params.id
        };
        Utils.checkMember(function(res){
            if(res.group!==1 && res.id!==parseInt($this.state.id)){
                Utils.alert('Access denied', function(){
                    window.location.href = Utils.url('index-show');
                });
                return false;
            }else if(res.group===1){
                Utils.request(Config.requestUrl+Utils.requestUrl('member-readById'), 'id='+$this.state.id, function(member){
                    $this.setState({
                        member: member,
                        memberCopy: res
                    })
                })
            }else{
                $this.setState({
                    member: res,
                    memberCopy: res
                })
            }
        })
    }

    input(e){
        e.preventDefault();
        let member = this.state.member;
        e = e.target;
        member[e.name] = e.value;
        this.setState({
            member: member
        });
    }

    submit(e){
        e.preventDefault();
        let postdata = this.state.member;
        postdata.cookie = Utils.getLoginCookie();
        Utils.request(Config.requestUrl+Utils.requestUrl('member-edit'), Utils.jsonToForm(postdata), function(res){
            Utils.alert(res);
        }, function(msg){
            Utils.alert(msg);
        });
    }

    render(){
        let member = this.state.member;
        return (
            <div>
                <Sider member={this.state.memberCopy} active1="Manage Member"></Sider>
                <Header title1={null} title2="Manage Member"></Header>

                <div className="wrap member-edit">
                    <div className="item">
                        <div className="title">MemberName:</div>
                        <div className="value">{member.membername}</div>
                    </div>
                    <div className="item">
                        <div className="title">Group:</div>
                        <div className="value">{member.groupObj.name}</div>
                    </div>
                    <div className="item">
                        <div className="title">RealName:</div>
                        <div className="value">{member.realName}</div>
                    </div>
                    <div className="item">
                        <div className="title">Email:</div>
                        <div className="value">
                            <input className="form-control" value={member.email} name="email" onChange={this.input.bind(this)} />
                        </div>
                    </div>
                    <div className="item">
                        <div className="title">Password:</div>
                        <div className="value">
                            <input className="form-control" value={member.password || ''} name="password" type="password" onChange={this.input.bind(this)} />
                        </div>
                    </div>
                    <button className="btn btn-success" onClick={this.submit.bind(this)}>Submit</button>
                </div>
            </div>
        )
    }
}

export default Edit;

