		return { error: new Error ("Bad uri") };
	}
	var arr = o.path.slice (1).split (";mode=");
	if (arr[1] && arr[1] !== "octet"){
		return this.fail (new Error ("The transfer mode must be 'octet'"));
	}
	return {
		host: o.host,
		port: o.port,
		file: arr[0]
	};
