def format_row(row, withLabel):
    try:
        fc = '${0:.2f}'.format(float(row[2]))
    except:
        fc = ''

    try:
        fd = '${0:.2f}'.format(float(row[3]))
    except:
        fd = ''

    s = extract_alphanumeric('{0} {1} {2} {3}'.format(row[1], fc, fd, row[4]))
