	if len(args) >= 1 && args[0] == "-" {

		scanner := bufio.NewScanner(os.Stdin)

		for scanner.Scan() {

			_, err := wr.Write(scanner.Bytes())

			if err != nil {
				log.Fatal(err)
			}
		}

	} else {

		msg := strings.Join(flag.Args(), " ")
		_, err := wr.Write([]byte(msg))

		if err != nil {
			log.Fatal(err)
		}
	}
}

