#include <I2CDeviceBootable.h>

I2CDeviceBootable::I2CDeviceBootable(I2CBus* bus, uint8_t address) : I2CDevice(bus, address)
{
}

void I2CDeviceBootable::checkRegisterMagic()
{
	uint8_t magic;
	i2cRead(
		I2C_DEVICE_BOOTABLE_REGISTER_BOOT_MAGIC,
		&magic, 1
	);

	if(magic != I2C_DEVICE_BOOTABLE_BOOT_MAGIC)
	{
		stringstream o;
		o << "Incorrect BOOTLOADER I2C DEVICE MAGIC NUMBER ";
		o << (int)magic;
		o << " ( expecting ";
		o << I2C_DEVICE_BOOTABLE_BOOT_MAGIC;
		o << " )";
		throw ios_base::failure(o.str());
	}
}

uint8_t I2CDeviceBootable::getRegisterBootStatus()
{
	uint8_t status;
	i2cRead(
		I2C_DEVICE_BOOTABLE_REGISTER_BOOT_STATUS,
		&status, 1
	);
	return status;
}

uint8_t I2CDeviceBootable::getRegisterBootVersion()
{
	uint8_t version;
	i2cRead(
		I2C_DEVICE_BOOTABLE_REGISTER_VERSION,
		&version, 1
	);
	return version;
}

uint8_t I2CDeviceBootable::getRegisterPageSize()
{
	uint8_t pageSize;
	i2cRead(
		I2C_DEVICE_BOOTABLE_REGISTER_PAGE_SIZE,
		&pageSize, 1
	);
	return pageSize;
}

uint16_t I2CDeviceBootable::getRegisterPageNumber()
{
	uint16_t pageNumber;
	i2cRead(
		I2C_DEVICE_BOOTABLE_REGISTER_PROGRAM_PAGE_NUMBER,
		(uint8_t*)&pageNumber, 2
	);
	return pageNumber;
}

uint8_t I2CDeviceBootable::getRegisterPageData()
{
	uint8_t pageData;
	i2cRead(
		I2C_DEVICE_BOOTABLE_REGISTER_PROGRAM_PAGE_DATA,
		(uint8_t*)&pageData, 1
	);
	return pageData;
}

void I2CDeviceBootable::writeBootStatus(uint8_t status)
{
	i2cWrite(
		I2C_DEVICE_BOOTABLE_REGISTER_BOOT_STATUS,
		&status, 1
	);
}

void I2CDeviceBootable::writePageNumber(uint16_t pageNumber)
{
	i2cWrite(
		I2C_DEVICE_BOOTABLE_REGISTER_PROGRAM_PAGE_NUMBER,
		(uint8_t*)&pageNumber, 2
	);
}

void I2CDeviceBootable::writePageData(vector<uint8_t> pageData)
{
	i2cWrite(
		I2C_DEVICE_BOOTABLE_REGISTER_PROGRAM_PAGE_DATA,
		pageData.data(), pageData.size()
	);
}

bool I2CDeviceBootable::inBootLoaderMode()
{
	checkRegisterMagic();

	return (getRegisterBootStatus() ==
		I2C_DEVICE_BOOTABLE_STATUS_BOOT_LOADER);
}

bool I2CDeviceBootable::inApplicationMode()
{
	checkRegisterMagic();

	return (getRegisterBootStatus() ==
		I2C_DEVICE_BOOTABLE_STATUS_APPLICATION);
}

package arithmospora

import (
	"fmt"

	"github.com/garyburd/redigo/redis"
)

type ProportionDataLoader interface {
	StatDataLoader
	FetchData() ([]int, error)
}

type ProportionData struct {
	Current    int
	Total      int
	dataLoader ProportionDataLoader
}

func (pd *ProportionData) Proportion() float64 {
	if pd.Total != 0 {
		return float64(pd.Current) / float64(pd.Total)
	} else {
		return 0
	}
}

func (pd *ProportionData) Percentage() float64 {
	return pd.Proportion() * 100
}

func (pd *ProportionData) Refresh() error {
	data, err := pd.dataLoader.FetchData()
	if err != nil {
		return err
	}

	pd.Current = data[0]
	pd.Total = data[1]
	return nil
}

func (pd *ProportionData) MarshalJSON() ([]byte, error) {
	return []byte(fmt.Sprintf(`{"current":%v,"total":%v,"proportion":%v,"percentage":%v}`, pd.Current, pd.Total, pd.Proportion(), pd.Percentage())), nil
}

func (pd *ProportionData) String() string {
	return fmt.Sprintf("current: %v, total: %v, proportion: %v, percentage: %v (%s)", pd.Current, pd.Total, pd.Proportion(), pd.Percentage(), pd.dataLoader)
}

func (pd *ProportionData) MilestoneValue(field string) float64 {
	switch field {
	case "current":
		return float64(pd.Current)
	case "proportion":
		return pd.Proportion()
	case "percentage":
		return pd.Percentage()
	}
	return 0.0
}

type ProportionDataLoaderRedis struct {
	RedisKeyMaker
}

func (pdl *ProportionDataLoaderRedis) FetchData() ([]int, error) {
	conn := RedisPool().Get()
	defer conn.Close()

	return redis.Ints(conn.Do("HMGET", pdl.MakeKey("data"), "current", "total"))
}

func (pdl *ProportionDataLoaderRedis) Load(*Stat) (StatData, error) {
	data, err := pdl.FetchData()
	if err != nil {
		return nil, err
	}

	return &ProportionData{Current: data[0], Total: data[1], dataLoader: pdl}, nil
}

func (pdl *ProportionDataLoaderRedis) String() string {
	return pdl.RedisKeyMaker.String()
}

