namespace Logic.Algorithms.Implementations._2D.Shelf
{
	public sealed class NextFitShelf2DAlgorithm : AbstractShelf2DAlgorithm
	{
		public NextFitShelf2DAlgorithm(Container2D initialContainer) : base(initialContainer)
		{
		}

		public override void Execute(ObjectSet originalObjects)
		{
			Position2D positionToPlace;

			ShelfContainer2D selectedContainer = containers.Last() as ShelfContainer2D;

			selectedContainer.AddShelf();

			ShelfSubContainer2D selectedShelf =  selectedContainer.TopShelf as ShelfSubContainer2D;

			var objectsCopy = originalObjects.ToObjectList();

			while (objectsCopy.Any())
			{
				Object2D selectedObject = objectsCopy.First() as Object2D;

				// Change Shelf
				if (selectedObject.Width + selectedShelf.LastPlacedObject.X2 > selectedContainer.Width)
				{
					selectedContainer.AddShelf();

					selectedShelf = selectedContainer.TopShelf as ShelfSubContainer2D;
				}

				// Change Container
				if (selectedObject.Height + selectedContainer.TopShelf.Y > selectedContainer.Height)
				{
					AddContainer();

					selectedContainer = containers.Last() as ShelfContainer2D;

					selectedContainer.AddShelf();

					selectedShelf = selectedContainer.TopShelf as ShelfSubContainer2D;
				}

				positionToPlace = new Position2D(selectedShelf.LastPlacedObject.X2, selectedShelf.Y);

				objectsCopy.Remove(selectedObject);
				selectedShelf.LastPlacedObject = selectedContainer.PlaceObject(selectedObject, positionToPlace) as PlacedObject2D;

			}
		}
	}
}

import { formatUnits } from '@ethersproject/units';

export class Token {
    constructor(chainId, address, decimals, symbol, name, logo, balance = null) {
        this.chainId = chainId
        this.address = address
        this.decimals = decimals
        this.symbol = symbol
        this.name = name
        this.logo = logo
        this.balance = balance
    }

    setBalance(balance) {
        this.balance = formatUnits(balance, this.decimals)
    }

    equals(withToken) {
        if (this === withToken) {
            return true
        }
        return this.chainId === withToken.chainId && this.address === withToken.address
    }
}

export class TokenAmount extends Token {
    constructor(token, amount) {
        super(token.chainId, token.address, token.decimals, token.symbol, token.name, token.logo)
        this.amount = formatUnits(amount, token.decimals)
    }

    equals(withToken) {
        if (this === withToken) {
            return true
        }
        return this.chainId === withToken.chainId && this.address === withToken.address
    }
}

export class WrapToken {
    constructor(name, symbol, sector, logo, chainId = 1, decimals, long_name, long_symbol, long_address, short_symbol, short_name, short_address) {
        this.name = name
        this.symbol = symbol
        this.sector = sector
        this.logo = logo
        this.chainId = chainId
        this.decimals = decimals
        this.long = new Token(chainId, long_address, decimals, long_symbol, long_name, logo)
        this.short = new Token(chainId, short_address, decimals, short_symbol, short_name, logo)
    }


    setBalance(balance, addressOrType) {
        if (addressOrType.substr(0, 2) === "0x") {
            if (this.long.address === addressOrType) {
                this.long.balance = formatUnits(balance, this.decimals)
            } else {
                this.short.balance = formatUnits(balance, this.decimals)
            }
        } else {
            this.setBalance(balance, addressOrType)
        }
    }

    setBalanceType(balance, type) {
        if (type === "long") {
            this.long.balance = formatUnits(balance, this.decimals)
        } else {
            this.short.balance = formatUnits(balance, this.decimals)
        }
    }

}

